'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const e = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={
  arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>', back:'<path d="M19 12H5m6-6-6 6 6 6"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',
  chat:'<path d="M4 4h16v12H9l-5 4V4Z"/><path d="M8 8h8m-8 4h5"/>',
  game:'<path d="M7 7h10c3 0 5 10 3 11-2 1-4-3-5-3H9c-1 0-3 4-5 3C2 17 4 7 7 7Z"/><path d="M8 9v5m-2.5-2.5h5M16 10h.01M18 13h.01"/>',
  music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="17" cy="16" rx="3" ry="3"/>',
  ball:'<circle cx="12" cy="12" r="9"/><path d="m12 7 5 4-2 6H9l-2-6 5-4Zm0-4v4m8 1-3 3m1 8-3-2m-9 2 3-2M4 8l3 3"/>',
  bolt:'<path d="m14 2-9 12h7l-2 8 9-12h-7l2-8Z"/>',
  spark:'<path d="m12 2 2.5 6.5L21 11l-6.5 2.5L12 20l-2.5-6.5L3 11l6.5-2.5L12 2ZM20 17v5m-2.5-2.5h5"/>',
  book:'<path d="M12 5C8 3 4 3 2 4v15c3-1 6-1 10 1 4-2 7-2 10-1V4c-2-1-6-1-10 1Zm0 0v15"/>',
  bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  trophy:'<path d="M7 3h10v6c0 4-2 6-5 6S7 13 7 9V3Zm0 2H3v3c0 3 2 4 5 4m9-7h4v3c0 3-2 4-5 4M12 15v6m-4 0h8"/>',
  print:'<path d="M7 8V3h10v5M7 17H3V8h18v9h-4M7 13h10v8H7v-8ZM17 10h1"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  heart:'<path d="M20.8 4.6c-2.4-2.3-5.8-1.8-8.8 1.3-3-3.1-6.4-3.6-8.8-1.3C.3 7.5 2.7 12.7 12 21c9.3-8.3 11.7-13.5 8.8-16.4Z"/>',
};
function icon(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;}
const themeMeta={Social:{color:'#e7e3ff',icon:'chat',label:'The group chat'},Gaming:{color:'#d8efbf',icon:'game',label:'In your gaming era'},Music:{color:'#ffdfc4',icon:'music',label:'On repeat'},Sport:{color:'#e6edb9',icon:'ball',label:'Game on'},Tech:{color:'#d9e8fc',icon:'bolt',label:'Future you'},IRL:{color:'#f6e5ed',icon:'spark',label:'Off-screen life'}};
const byId = id=>LESSONS.find(l=>l.id===id);
const lessonInterests=l=>[l.theme,...(l.interests||[])];
const questionKey=(id,index)=>`${id}:${index}`;
const validKey=key=>typeof key==='string'&&LESSONS.some(l=>l.questions.some((_,i)=>questionKey(l.id,i)===key));
const fresh=()=>({answers:{},results:{},saved:[],mistakes:[],days:[],applied:[],exerciseAnswers:{},lastLesson:null});
let storageAvailable=true, state=fresh(), session=null, library={level:'All',topic:'All',theme:'All',q:'',saved:false}, practiceMode='mix',teacherId=LESSONS[0].id,teacherAnswers=false,toastTimer;
try{
  const raw=JSON.parse(localStorage.getItem('english-bro-v1')||'null');
  if(raw&&typeof raw==='object'){
    state.saved=Array.isArray(raw.saved)?raw.saved.filter(id=>byId(id)):[];
    state.applied=Array.isArray(raw.applied)?raw.applied.filter(id=>byId(id)):[];
    state.mistakes=Array.isArray(raw.mistakes)?raw.mistakes.filter(validKey):[];
    state.days=Array.isArray(raw.days)?raw.days.filter(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)):[];
    state.lastLesson=byId(raw.lastLesson)?raw.lastLesson:null;
    restoreExerciseProgress(raw.exerciseAnswers);
    if(raw.answers&&typeof raw.answers==='object')for(const [key,value] of Object.entries(raw.answers))if(validKey(key)&&value===true)state.answers[key]=true;
    if(raw.results&&typeof raw.results==='object')for(const [id,r] of Object.entries(raw.results))if(byId(id)&&r&&Number.isInteger(r.best)&&r.best>=0&&r.best<=5)state.results[id]={best:r.best,attempts:Number.isInteger(r.attempts)?r.attempts:1};
  }
}catch{storageAvailable=false;}
function save(){try{localStorage.setItem('english-bro-v1',JSON.stringify(state));}catch{storageAvailable=false;}}
function todayKey(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function streak(){let count=0,date=new Date();if(!state.days.includes(todayKey(date)))date.setDate(date.getDate()-1);while(state.days.includes(todayKey(date))){count++;date.setDate(date.getDate()-1);}return count;}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function completed(id){return (state.results[id]?.best||0)>=4;}
function topicFor(id){return TOPICS.find(t=>t.lessons.includes(id));}
function header(active){
  return `<header class="site-header"><div class="wrap header-inner">
    <a href="#/" class="brand" aria-label="English, Bro home"><img class="brand-logo" src="english-bro-logo.png" alt="English, Bro" width="240" height="80"></a>
    <nav class="main-nav" id="navigation" aria-label="Main navigation">
      <a class="nav-link ${active==='learn'?'active':''}" href="#/learn" ${active==='learn'?'aria-current="page"':''}>All lessons</a>
      <details class="nav-dropdown"><summary>By level ${icon('chevron',12)}</summary><div class="nav-panel level-menu"><p class="menu-eyebrow">CHOOSE YOUR LEVEL</p>${LEVELS.map(level=>`<a href="#/learn?level=${level}"><span class="menu-level">${level}</span><span><strong>${LEVEL_LABELS[level]}</strong><small>${LESSONS.filter(l=>l.level===level).length} lessons</small></span>${icon('arrow',14)}</a>`).join('')}<a class="menu-footer" href="#/paths">Follow a learning path ${icon('arrow',14)}</a></div></details>
      <details class="nav-dropdown"><summary>By topic ${icon('chevron',12)}</summary><div class="nav-panel topic-menu"><p class="menu-eyebrow">WHAT ARE YOU WORKING ON?</p><div class="topic-menu-grid">${TOPICS.map(t=>`<a href="#/learn?topic=${t.id}"><span>${e(t.title)}</span><small>${t.lessons.length}</small></a>`).join('')}</div><a class="menu-footer" href="#/learn">Browse all ${LESSONS.length} lessons ${icon('arrow',14)}</a></div></details>
      <a class="nav-link ${active==='exercises'?'active':''}" href="#/exercises" ${active==='exercises'?'aria-current="page"':''}>Exercises</a>
      <a class="nav-link ${active==='teachers'?'active':''}" href="#/teachers" ${active==='teachers'?'aria-current="page"':''}>For teachers</a>
    </nav>
    <a class="progress-link" href="#/progress" ${active==='progress'?'aria-current="page"':''}><span class="avatar">${icon('bolt',15)}</span><span class="progress-word">My progress</span><span>${Object.keys(state.answers).length*10} XP</span></a>
    <button class="menu-toggle" aria-controls="navigation" aria-expanded="false" aria-label="Open navigation">${icon('menu',23)}</button>
  </div></header>`;
}
function finder(scope,values={level:'All',topic:'All',q:''}){
  return `<form class="lesson-finder ${scope==='home'?'home-finder':''}" data-finder="${scope}" role="search" aria-label="${scope==='exercises'?'Find exercises':'Find a lesson'}">
    ${scope==='home'?`<div class="finder-intro"><span class="finder-kicker">GOT HOMEWORK?</span><h2>Find your lesson.</h2><p>Your topic. Your level. Straight in.</p></div>`:''}
    <div class="finder-fields"><div class="field"><label for="${scope}-level">Level</label><select id="${scope}-level" name="level"><option value="All">All levels</option>${LEVELS.map(x=>`<option value="${x}" ${values.level===x?'selected':''}>${x} · ${LEVEL_LABELS[x]}</option>`).join('')}</select></div>
    <div class="field"><label for="${scope}-topic">Grammar topic</label><select id="${scope}-topic" name="topic"><option value="All">All grammar topics</option>${TOPICS.map(t=>`<option value="${t.id}" ${values.topic===t.id?'selected':''}>${e(t.title)}</option>`).join('')}</select></div>
    <div class="field finder-search"><label for="${scope}-search">Find a specific lesson</label><div class="finder-input">${icon('search',17)}<input id="${scope}-search" name="q" type="search" placeholder="Try “present simple”…" value="${e(values.q)}" autocomplete="off"></div></div>
    <button class="button dark" type="submit">${scope==='exercises'?'Find exercises':'Find lessons'} ${icon('arrow',17)}</button></div>
  </form>`;
}
function bindFinder(scope){
  const form=document.querySelector(`[data-finder="${scope}"]`);
  const values=()=>({level:form.elements.level.value,topic:form.elements.topic.value,q:form.elements.q.value});
  form.addEventListener('submit',ev=>{ev.preventDefault();if(scope==='home'){library={...values(),theme:'All',saved:false};location.hash=libraryUrl();}else{Object.assign(library,values());updateLibrary();$('#catalogue-title').focus({preventScroll:true});$('#catalogue-title').scrollIntoView({block:'start',behavior:'smooth'});}});
  if(scope==='library')for(const field of [form.elements.level,form.elements.topic,form.elements.q])field.addEventListener(field.type==='search'?'input':'change',()=>{Object.assign(library,values());updateLibrary();});
}
function topicDirectory(){return `<section class="section topic-directory" aria-labelledby="topics-title"><div class="section-heading"><div><div class="eyebrow">GRAMMAR. EASY TO FIND.</div><h2 id="topics-title">What’s the assignment?</h2><p class="section-sub">Choose the topic from class. We’ll bring the context.</p></div><a href="#/learn" class="text-link">All lessons ${icon('arrow',16)}</a></div><div class="topic-directory-grid">${TOPICS.map(t=>`<a href="#/learn?topic=${t.id}" class="topic-directory-card"><span class="topic-directory-icon">${icon(t.icon,21)}</span><div><h3>${e(t.title)}</h3><p>${e(t.description)}</p><small>${t.lessons.length} ${t.lessons.length===1?'lesson':'lessons'} · ${[...new Set(t.lessons.map(id=>byId(id).level))].join(' / ')}</small></div>${icon('arrow',17)}</a>`).join('')}</div></section>`;}
function footer(){return `<footer class="site-footer"><div class="wrap footer-inner"><div><a class="footer-brand" href="#/" aria-label="English, Bro home"><img class="footer-logo" src="english-bro-logo.png" alt="English, Bro" width="150" height="50"></a><p class="footer-note">A little practice. A lot more confidence.</p></div><div class="footer-links"><a href="#/learn">All lessons</a><a href="#/exercises">Exercises</a><a href="#/paths">Learning paths</a><a href="#/teachers">Teacher tools</a><a href="#/about">About & privacy</a></div><p class="footer-note">English first. Everyone welcome.<br>Original lessons · British English</p></div></footer>`;}
function shell(content,active){
  $('#app').innerHTML=header(active)+`<main id="main" tabindex="-1">${content}</main>`+footer();
  $('.menu-toggle').addEventListener('click',ev=>{const b=ev.currentTarget;const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'Close navigation':'Open navigation');$('#navigation').classList.toggle('open',open);if(!open)document.querySelectorAll('.nav-dropdown[open]').forEach(d=>d.open=false);});
  document.querySelectorAll('.nav-dropdown').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.nav-dropdown').forEach(other=>{if(other!==d)other.open=false;});}));
  $('#navigation').addEventListener('click',ev=>{if(ev.target.closest('a'))document.querySelectorAll('.nav-dropdown[open]').forEach(d=>d.open=false);});
}
document.addEventListener('click',ev=>{if(!ev.target.closest('.nav-dropdown'))document.querySelectorAll('.nav-dropdown[open]').forEach(d=>d.open=false);});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){const open=document.querySelector('.nav-dropdown[open]');if(open){open.open=false;open.querySelector('summary').focus();}else if($('#navigation')?.classList.contains('open'))$('.menu-toggle').click();}});
function card(l){const m=themeMeta[l.theme];return `<article class="lesson-card" style="--tone:${m.color}"><button class="bookmark ${state.saved.includes(l.id)?'saved':''}" data-save="${l.id}" aria-label="${state.saved.includes(l.id)?'Unsave':'Save'} ${e(l.grammar)}" aria-pressed="${state.saved.includes(l.id)}">${icon('bookmark',15)}</button>${completed(l.id)?`<span class="card-complete">${icon('check',11)} CHALLENGE PASSED</span>`:''}<a href="#/lesson/${l.id}" class="card-art" tabindex="-1" aria-hidden="true"><span class="card-art-label">${e(l.title)}</span><span class="card-art-icon">${icon(l.icon,55)}</span></a><a class="card-content" href="#/lesson/${l.id}"><div class="card-meta"><span class="level-badge">${l.level}</span><span>${e(l.theme)}</span><span>·</span><span>${l.minutes} MIN</span></div><h3>${e(l.grammar)}</h3><p>${e(l.hook)}</p><div class="card-bottom"><span>${completed(l.id)?'Revisit lesson':'Learn & practise'}</span><span class="arrow-circle">${icon('arrow',15)}</span></div></a></article>`;}
function bindSaved(){document.querySelectorAll('[data-save]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.save,isSaved=state.saved.includes(id);state.saved=isSaved?state.saved.filter(s=>s!==id):[...state.saved,id];save();b.classList.toggle('saved',!isSaved);if(!b.classList.contains('bookmark'))b.innerHTML=icon('bookmark',15)+' '+(isSaved?'Save for later':'Saved lesson');b.setAttribute('aria-pressed',String(!isSaved));b.setAttribute('aria-label',`${isSaved?'Save':'Unsave'} ${byId(id).grammar}`);toast(isSaved?'Lesson removed from your saved list.':'Saved. Find it in My progress.');if(location.hash.startsWith('#/learn')&&library.saved)updateLibrary();}));}
function home(){
  shell(`<div class="wrap">${finder('home')}<section class="hero"><div><div class="eyebrow"><span class="status-dot"></span>YOUR WORLD. IN ENGLISH.</div><h1>English for<br>your <span class="highlight">actual</span><br>life.</h1><p class="hero-copy">From the group chat to the exam paper. Learn the rules through the things you’re already into.</p><div class="hero-actions"><a href="#/learn" class="button dark">Find your next lesson ${icon('arrow',18)}</a><a href="#/exercises" class="button">Get practising ${icon('bolt',17)}</a></div><p class="microcopy">${icon('check',13)} Free to explore <span>·</span> A1–B2 <span>·</span> No student account needed</p></div><div class="hero-art"><div class="art-grid"></div><div class="art-star">${icon('spark',65)}</div><div class="floating-sticker">SMALL LESSON. BIG ENERGY.</div><div class="quiz-preview"><div class="card-eyebrow"><span><span class="live-dot"></span>THE GROUP CHAT</span><span class="tag">B1 · CONDITIONALS</span></div><div class="message"><div class="message-user"><span class="message-avatar">J</span><strong>JAMIE</strong><span>just now</span></div><p>If this video <span class="inline-blank" id="hero-blank">___</span><br>a million views,<br>I’ll dye my hair.</p></div><p class="preview-prompt">You’re the grammar check. Pick one.</p><div class="preview-options"><button class="preview-option" data-preview="gets">gets</button><button class="preview-option" data-preview="will get">will get</button><button class="preview-option" data-preview="got">got</button></div><div class="preview-feedback" id="hero-feedback" role="status">A real-life sentence. One useful rule.</div></div><div class="floating-note">${icon('bolt',17)} Ohhh. That actually makes sense.</div></div></section><div class="info-strip"><div class="info-item"><span class="info-icon">${icon('book',17)}</span><span><strong>${LESSONS.length} bite-size lessons</strong><br>Clear rules. Relevant examples.</span></div><div class="info-item"><span class="info-icon">${icon('bolt',17)}</span><span><strong>${LESSONS.reduce((n,l)=>n+l.questions.length,0)+EXERCISE_SETS.reduce((n,s)=>n+exerciseItems(s).length,0)} practice questions</strong><br>Feedback that tells you why.</span></div><div class="info-item"><span class="info-icon">${icon('heart',17)}</span><span><strong>Your pace. No pressure.</strong><br>Build confidence, one win at a time.</span></div></div><section class="path-teaser"><div><span class="eyebrow">A CLEAR ROUTE FORWARD</span><h2>Find your starting point.</h2><p>Follow a level path, with a clear goal for every lesson.</p></div><a href="#/paths" class="button">Choose a learning path ${icon('arrow',17)}</a></section>${topicDirectory()}<section class="world-panel" aria-labelledby="world-title"><div><div class="eyebrow" style="color:#c6fa58;margin-bottom:14px">FOLLOW YOUR INTERESTS</div><h2 id="world-title">Your world.<br><span>Your words.</span></h2><p>Into gaming? Here for the music? Start with something you actually want to talk about.</p></div><div class="theme-grid">${THEMES.map(t=>`<a href="#/learn?theme=${t}" class="theme-tile">${icon(themeMeta[t].icon,25)}<span>${t==='IRL'?'Everyday life':t}</span></a>`).join('')}</div></section></div>`,'home');
  bindSaved();
  bindFinder('home');
  document.querySelectorAll('[data-preview]').forEach(b=>b.addEventListener('click',()=>{const right=b.dataset.preview==='gets';document.querySelectorAll('[data-preview]').forEach(x=>{x.disabled=true;x.classList.toggle('correct',x.dataset.preview==='gets');x.classList.toggle('wrong',x===b&&!right);});$('#hero-blank').textContent='gets';$('#hero-feedback').innerHTML=`<strong>${right?'You got it.':'Almost! Use “gets”.'}</strong> Present simple after <em>if</em>, <em>will</em> in the result. <a href="#/lesson/first-conditional" style="text-decoration:underline">See why →</a>`;}));
}
function searchText(value){return String(value).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
function filteredLessons(){
  const words=searchText(library.q).split(' ').filter(Boolean);
  const ordered=PATHS.flatMap(p=>p.order.map(byId));
  return ordered.filter(l=>(library.level==='All'||l.level===library.level)&&(library.topic==='All'||topicFor(l.id).id===library.topic)&&(library.theme==='All'||lessonInterests(l).includes(library.theme))&&(!library.saved||state.saved.includes(l.id))&&words.every(word=>searchText(`${l.title} ${l.grammar} ${l.hook} ${l.theme} ${(l.contexts||[]).join(' ')} ${topicFor(l.id).title} ${LESSON_SEARCH[l.id]||''}`).includes(word)));
}
function libraryUrl(){const p=new URLSearchParams();if(library.level!=='All')p.set('level',library.level);if(library.topic!=='All')p.set('topic',library.topic);if(library.theme!=='All')p.set('theme',library.theme);if(library.q)p.set('q',library.q);if(library.saved)p.set('saved','1');return '#/learn'+(p.size?'?'+p:'');}
function syncFinder(){const form=document.querySelector('[data-finder="library"]');if(form){form.elements.level.value=library.level;form.elements.topic.value=library.topic;form.elements.q.value=library.q;}$('#interest-filter').value=library.theme;$('#saved-filter').classList.toggle('active',library.saved);$('#saved-filter').setAttribute('aria-pressed',String(library.saved));}
function updateLibrary(){
  const list=filteredLessons(),topic=TOPICS.find(t=>t.id===library.topic),hasFilters=library.level!=='All'||topic||library.theme!=='All'||library.q||library.saved;
  $('#catalogue-title').textContent=topic?topic.title:library.q?`Results for “${library.q}”`:library.saved?'Your saved lessons':'Your lesson library.';
  $('#result-number').textContent=`${list.length} ${list.length===1?'lesson':'lessons'}${library.level!=='All'?' · '+library.level+' · '+LEVEL_LABELS[library.level]:''}`;
  $('#clear-filters').hidden=!hasFilters;
  const chips=[library.level!=='All'?['level',`${library.level} · ${LEVEL_LABELS[library.level]}`]:null,topic?['topic',topic.title]:null,library.q?['q',`Search: ${library.q}`]:null,library.theme!=='All'?['theme',library.theme==='IRL'?'Everyday life':library.theme]:null,library.saved?['saved','Saved lessons']:null].filter(Boolean);
  $('#active-filters').innerHTML=chips.map(([key,label])=>`<button class="filter-chip" data-remove-filter="${key}" aria-label="Remove ${e(label)} filter">${e(label)} ${icon('close',12)}</button>`).join('');
  document.querySelectorAll('[data-remove-filter]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.removeFilter;library[key]=key==='saved'?false:key==='q'?'':'All';syncFinder();updateLibrary();}));
  $('#library-grid').innerHTML=list.length?LEVELS.map(level=>{const lessons=list.filter(l=>l.level===level);return lessons.length?`<section class="catalogue-level" aria-labelledby="heading-${level}"><div class="catalogue-level-heading"><div><span class="catalogue-level-badge">${level}</span><h3 id="heading-${level}">${LEVEL_LABELS[level]}</h3><span>${lessons.length} ${lessons.length===1?'lesson':'lessons'}</span></div><a class="text-link" href="#/paths?level=${level}">See learning path ${icon('arrow',14)}</a></div><div class="lesson-grid">${lessons.map(card).join('')}</div></section>`:'';}).join(''):`<div class="empty catalogue-empty"><span class="topic-directory-icon">${icon('search',25)}</span><h3>No lessons match these filters yet.</h3><p>Try a broader level or remove a filter above. Every lesson in this collection is available without an interest filter.</p><div class="result-actions">${library.level!=='All'?'<button class="button small dark" data-broaden="level">Try all levels</button>':''}${library.theme!=='All'?'<button class="button small" data-broaden="theme">Try all interests</button>':''}<button class="button small" id="clear-empty">Show all lessons</button></div></div>`;
  bindSaved();$('#clear-empty')?.addEventListener('click',resetLibrary);
  document.querySelectorAll('[data-broaden]').forEach(b=>b.addEventListener('click',()=>{library[b.dataset.broaden]='All';syncFinder();updateLibrary();}));
  history.replaceState(null,'',libraryUrl());
  document.title=`${topic?topic.title:'Find a lesson'} — English, Bro`;
}
function resetLibrary(){library={level:'All',topic:'All',theme:'All',q:'',saved:false};syncFinder();updateLibrary();}
function learn(params){
  if(params){library.level=LEVELS.includes(params.get('level'))?params.get('level'):'All';library.topic=TOPICS.some(t=>t.id===params.get('topic'))?params.get('topic'):'All';library.theme=THEMES.includes(params.get('theme'))?params.get('theme'):'All';library.q=params.get('q')||'';library.saved=params.get('saved')==='1';}
  shell(`<div class="wrap bottom-space"><section class="page-top catalogue-intro"><div class="eyebrow">YOUR TOPIC. YOUR LEVEL. YOUR WORLD.</div><h1>Find it. Get it. Use it.</h1><p class="section-sub">Got a topic from class? Find the rule, practise it, then make it yours.</p></section>
    ${finder('library',library)}
    <div class="library-extra"><div class="interest-control"><label for="interest-filter">Make it your world <span>(optional)</span></label><select id="interest-filter"><option value="All">All interests</option>${THEMES.map(t=>`<option value="${t}" ${library.theme===t?'selected':''}>${t==='IRL'?'Everyday life':t}</option>`).join('')}</select></div><button class="pill filter-bookmark ${library.saved?'active':''}" id="saved-filter" aria-pressed="${library.saved}">${icon('bookmark',14)} Saved lessons</button></div>
    <div id="active-filters" class="active-filters" aria-label="Active filters"></div><section class="catalogue-results" aria-labelledby="catalogue-title"><div class="catalogue-results-heading"><div><h2 id="catalogue-title" tabindex="-1"></h2><p id="result-number" role="status" aria-live="polite"></p></div><button id="clear-filters" class="text-link">Clear filters</button></div><div id="library-grid"></div></section><p class="practice-disclaimer">Level labels guide lesson difficulty. This collection is a starting library, rather than a complete CEFR course.</p></div>`,'learn');
  updateLibrary();bindFinder('library');
  $('#interest-filter').addEventListener('change',ev=>{library.theme=ev.target.value;updateLibrary();});
  $('#saved-filter').addEventListener('click',()=>{library.saved=!library.saved;syncFinder();updateLibrary();});
  $('#clear-filters').addEventListener('click',resetLibrary);
}
function lesson(id){
  const l=byId(id);if(!l){notFound();return;}state.lastLesson=id;save();const m=themeMeta[l.theme],learn=LEARNING[id];
  const passed=(state.results[id]?.best||0)>=4;
  shell(`<div class="wrap"><div class="page-top" style="padding-bottom:18px"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="#/learn">All lessons</a>${icon('chevron',12)}<a href="#/learn?level=${l.level}">${l.level}</a>${icon('chevron',12)}<a href="#/learn?topic=${topicFor(id).id}">${e(topicFor(id).title)}</a>${icon('chevron',12)}<span>${e(l.grammar)}</span></nav></div><div class="lesson-layout"><div><section class="lesson-heading" style="--tone:${m.color}"><div class="card-meta"><span class="level-badge">${l.level}</span><span>${e(l.theme)}</span><span>·</span><span>${l.minutes} MIN</span></div><h1>${e(l.title)}</h1><p><strong>${e(l.grammar)}</strong> · ${e(l.hook)}</p></section><section class="learning-goals"><div class="eyebrow">BY THE END, YOU CAN…</div><ul>${learn.goals.map(g=>`<li>${icon('check',15)}<span>${e(g)}</span></li>`).join('')}</ul></section><section class="panel scene-panel"><div class="eyebrow" style="margin-bottom:18px">01 / NOTICE IT IN THE WILD</div><h2>First, a real conversation.</h2>${learn.context?`<p class="scene-context">${e(learn.context)}</p>`:''}<div class="scene-thread">${learn.scene.map(([name,text],i)=>`<div class="scene-message ${i%2?'reply':''}"><span>${e(name)}</span><p>${e(text)}</p></div>`).join('')}</div><details class="notice"><summary>What should I notice?</summary><p>${e(learn.notice)}</p></details></section><section class="panel"><div class="eyebrow" style="margin-bottom:16px">02 / UNDERSTAND THE PATTERN</div><h2>Make sense of the rule.</h2><p class="rule-text">${e(l.rule)}</p><div class="formula">${e(l.form)}</div>${l.examples.map(([text,note])=>`<div class="example"><p>${e(text)}</p><small>${e(note)}</small></div>`).join('')}<div class="watch-out">${icon('bolt',21)}<div><strong>Watch this bit.</strong>${e(l.watchOut)}</div></div></section><section class="panel challenge-callout"><div><div class="eyebrow">03 / CHECK YOUR UNDERSTANDING</div><h2>Put the pattern to work.</h2><p>Five questions, with an explanation for every answer.</p></div><a href="#/quiz/${l.id}" class="button dark">Try the challenge ${icon('arrow',17)}</a></section><section class="panel mission-box"><div class="eyebrow" style="margin-bottom:14px">04 / MAKE IT YOURS</div><h2>Your turn to use it.</h2><p>${e(l.mission)}</p><div class="self-check"><strong>Check your own work</strong><ul><li>Did I use the target grammar?</li><li>Does my message make sense?</li><li>Can I explain one grammar choice I made?</li></ul><p class="tiny muted">Try this aloud, with a partner, or in your notebook. Ask a partner or teacher for feedback; this task is not automatically marked.</p></div><label class="checkbox-label apply-check"><input id="apply-task" type="checkbox" ${state.applied.includes(id)?'checked':''}>I’ve tried the task and checked my work.</label></section><a href="#/paths?level=${l.level}" class="text-link">Back to the ${l.level} learning path ${icon('arrow',17)}</a></div><aside class="lesson-sidebar"><div class="panel"><div class="sidebar-label">YOUR LEARNING ROUTE</div><h3>${e(l.grammar)}</h3><ol class="step-list"><li><span class="step-number">1</span>Notice it in context</li><li><span class="step-number">2</span>Understand the pattern</li><li><span class="step-number">3</span>Check your understanding</li><li><span class="step-number">4</span>Make it yours</li></ol><a href="#/quiz/${l.id}" class="button dark full">Let’s practise ${icon('arrow',16)}</a>${state.results[id]?`<p class="side-note">Your best score: <strong>${state.results[id].best}/5</strong>. ${passed?'Challenge passed. Try the real-life task next.':'Get 4/5 to pass this challenge.'}</p>`:'<p class="side-note">Get 4 out of 5 to pass the challenge. Then put the grammar to work in the real-life task.</p>'}</div><div class="panel"><button class="button small full" data-save="${l.id}" aria-pressed="${state.saved.includes(id)}">${icon('bookmark',15)} ${state.saved.includes(id)?'Saved lesson':'Save for later'}</button>${exerciseById(id)?`<a class="button small full mt10" href="#/exercises/${id}">${icon('book',15)} 20 practice exercises</a>`:''}<button class="button small full mt10" id="lesson-print">${icon('print',15)} Print worksheet</button></div></aside></div></div>`,'learn');
  bindSaved();$('#lesson-print').addEventListener('click',()=>printWorksheet(id,false));$('#apply-task').addEventListener('change',ev=>{state.applied=ev.target.checked?[...new Set([...state.applied,id])]:state.applied.filter(x=>x!==id);save();toast(ev.target.checked?'Real-life task marked as tried. Keep using it.':'Task marked as still to try.');});
}
function shuffled(array){const a=[...array];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function refsFor(lessons){return lessons.flatMap(l=>l.questions.map((_,index)=>({id:l.id,index})));}
function startSession(refs,title,lessonId=null,returnTo='#/practice'){
  session={refs,title,lessonId,returnTo,index:0,answers:[],selected:'',checked:false,finished:false,startXP:Object.keys(state.answers).length*10};
  if(location.hash==='#/session')renderSession();else location.hash='#/session';
}
function practice(){shell(`<div class="wrap"><div class="practice-container"><section class="practice-intro"><div class="eyebrow">LESS SCROLLING. MORE KNOWING.</div><h1>A little brain workout.</h1><p>Choose your mix. Answer ten questions. Leave with something that sticks.</p></section><form class="practice-form" id="practice-form"><h2 style="font-size:25px">What are we working on?</h2><div class="practice-mode"><button type="button" class="mode-button ${practiceMode==='mix'?'selected':''}" data-mode="mix" aria-pressed="${practiceMode==='mix'}"><strong>${icon('bolt',17)} A fresh mix</strong><small>Questions from across the library</small></button><button type="button" class="mode-button ${practiceMode==='review'?'selected':''}" data-mode="review" aria-pressed="${practiceMode==='review'}"><strong>${icon('heart',16)} My tricky bits</strong><small>${state.mistakes.length} ${state.mistakes.length===1?'question':'questions'} to revisit</small></button></div><div class="form-grid" id="practice-filters"><div class="field"><label for="practice-level">Your level</label><select id="practice-level"><option value="All">Mix all levels</option>${LEVELS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="practice-theme">Your world</label><select id="practice-theme"><option value="All">A bit of everything</option>${THEMES.map(x=>`<option value="${x}">${x==='IRL'?'Everyday life':x}</option>`).join('')}</select></div></div><p class="tiny muted mt20" id="practice-mode-help">10 questions · Multiple choice + fill in the gap · No timer</p><button class="button dark full mt20" type="submit">Let’s do this ${icon('arrow',18)}</button><p class="tiny muted mt10" id="practice-error" role="status"></p></form><p class="practice-disclaimer">This is practice, not a formal placement test. A mistake is a useful place to start.</p></div></div>`,'practice');
  const sync=()=>{$('#practice-filters').hidden=practiceMode==='review';$('#practice-mode-help').textContent=practiceMode==='review'?'Up to 10 questions you previously missed · Work through them at your pace':'10 questions · Multiple choice + fill in the gap · No timer';};sync();document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{practiceMode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#practice-error').textContent='';sync();}));
  $('#practice-form').addEventListener('submit',ev=>{ev.preventDefault();let pool;if(practiceMode==='review')pool=state.mistakes.map(key=>{const [id,qi]=key.split(':');return {id,index:Number(qi)};});else{const level=$('#practice-level').value,theme=$('#practice-theme').value;pool=refsFor(LESSONS.filter(l=>(level==='All'||l.level===level)&&(theme==='All'||lessonInterests(l).includes(theme))));}if(!pool.length){$('#practice-error').textContent=practiceMode==='review'?'No tricky bits yet. Try a fresh mix first.':'No questions in this combination yet. Try another level or interest.';return;}startSession(shuffled(pool).slice(0,10),practiceMode==='review'?'Your tricky bits':'Your fresh mix');});
}
function normalise(s){return String(s).trim().toLowerCase().replace(/[‘’]/g,"'").replace(/\s+/g,' ').replace(/[.!?]+$/,'');}
function isCorrect(q,value){const expected=Array.isArray(q.answer)?q.answer:[q.answer];return expected.some(a=>normalise(a)===normalise(value));}
function recordAnswer(ref,correct){const key=questionKey(ref.id,ref.index);if(correct){state.answers[key]=true;state.mistakes=state.mistakes.filter(k=>k!==key);}else if(!state.mistakes.includes(key))state.mistakes.push(key);const day=todayKey();if(!state.days.includes(day))state.days.push(day);save();}
function renderSession(){if(!session){practice();return;}if(session.finished){renderResult();return;}const ref=session.refs[session.index],l=byId(ref.id),q=l.questions[ref.index],correct=session.checked&&isCorrect(q,session.selected);const answer=Array.isArray(q.answer)?q.answer[0]:q.answer;
  shell(`<div class="wrap"><div class="practice-container"><div class="session-header"><div><p class="session-meta">${e(session.title)}</p><h1 class="session-heading">One question. One small win.</h1></div><a class="back-link" href="${e(session.returnTo)}" aria-label="Leave practice">${icon('close',19)} Exit</a></div><div class="session-progress"><div class="results-count"><span>Question ${session.index+1} of ${session.refs.length}</span><span>${session.answers.filter(x=>x.correct).length} correct</span></div><div class="progress-bar"><span style="width:${session.index/session.refs.length*100}%"></span></div></div><form id="question-form" class="question-panel"><div class="question-kicker"><span>${e(l.grammar)}</span><span class="tag">${l.level} · ${e(l.theme)}</span></div><h2 class="question-prompt">${e(q.prompt)}</h2>${q.options?`<div class="question-options" role="group" aria-label="Answer options">${q.options.map((option,i)=>`<button type="button" class="answer-option ${session.selected===option?'selected':''} ${session.checked&&isCorrect(q,option)?'correct':''} ${session.checked&&session.selected===option&&!correct?'wrong':''}" data-option="${i}" aria-pressed="${session.selected===option}" ${session.checked?'disabled':''}><span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${e(option)}</span>${session.checked&&isCorrect(q,option)?`<span style="margin-left:auto">${icon('check',18)}</span>`:''}</button>`).join('')}</div>`:`<label class="skip-link" style="position:absolute" for="typed-answer">Your answer</label><input class="answer-input" id="typed-answer" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="Type the missing word or words" placeholder="Type the missing word or words…" value="${e(session.selected)}" ${session.checked?'disabled':''}><p class="input-help">Write only the missing words. Capital letters and curly apostrophes are accepted.</p>`}${session.checked?`<div class="feedback ${correct?'':'incorrect'}" role="status" tabindex="-1"><h3>${icon(correct?'check':'bolt',19)} ${correct?'That’s the one.':'Not quite. Here’s why.'}</h3>${!correct?`<span class="correct-answer">Answer: ${e(answer)}</span>`:''}<p>${e(q.why)}</p></div>`:''}<div class="question-actions"><small>${session.checked?'Read the why. Take it with you.':'Pick an answer, then check it.'}</small><button class="button ${session.checked?'dark':'lime'}" id="check-answer" type="submit" ${!session.checked&&!session.selected?'disabled':''}>${session.checked?(session.index===session.refs.length-1?'See my results':'Next question'):'Check answer'} ${icon('arrow',17)}</button></div></form><p class="practice-disclaimer">Your score uses your first answer to each question in this round.</p></div></div>`,'practice');
  document.querySelectorAll('[data-option]').forEach(b=>b.addEventListener('click',()=>{if(session.checked)return;session.selected=q.options[Number(b.dataset.option)];document.querySelectorAll('[data-option]').forEach(x=>{const selected=x===b;x.classList.toggle('selected',selected);x.setAttribute('aria-pressed',String(selected));});$('#check-answer').disabled=false;}));$('#typed-answer')?.addEventListener('input',ev=>{session.selected=ev.target.value;$('#check-answer').disabled=!session.selected.trim();});
  $('#question-form').addEventListener('submit',ev=>{ev.preventDefault();if(session.checked){if(session.index===session.refs.length-1){session.finished=true;if(session.lessonId){const correctCount=session.answers.filter(x=>x.correct).length;const old=state.results[session.lessonId];state.results[session.lessonId]={best:Math.max(old?.best||0,correctCount),attempts:(old?.attempts||0)+1};save();}renderResult();}else{session.index++;session.selected='';session.checked=false;renderSession();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}else{if(!session.selected.trim())return;const right=isCorrect(q,session.selected);session.checked=true;session.answers.push({ref,answer:session.selected,correct:right});recordAnswer(ref,right);renderSession();$('.feedback').focus({preventScroll:true});}});
}
function renderResult(){const s=session;if(!s){practice();return;}const correct=s.answers.filter(x=>x.correct).length,total=s.refs.length,wrong=s.answers.filter(x=>!x.correct),earned=Object.keys(state.answers).length*10-s.startXP;const pass=correct/total>=.8;
  shell(`<div class="wrap"><div class="practice-container"><section class="session-result"><div class="result-icon">${icon(pass?'trophy':'spark',36)}</div><p class="eyebrow" style="justify-content:center;margin-bottom:14px">${e(s.title)}</p><div class="score-number">${correct}<span> / ${total}</span></div><h1>${correct===total?'Clean sweep. Nicely done.':pass?'Solid work. Keep it going.':'The tricky bits are the useful bits.'}</h1><p>${s.lessonId?(pass?'Challenge passed. Try the real-life task to put the rule to work.':'Get at least 4 out of 5 in one round to pass this challenge. The explanations below can help.'):(wrong.length?'Your missed questions are saved in My tricky bits. Come back and make them stick.':'You’ve got this mix. Try another level or interest next.')}</p><div class="badge-light mt20">${icon('bolt',14)} +${earned} new XP <span>·</span> ${earned?'Progress saved':'Previously earned questions don’t add extra XP'}</div><div class="result-actions"><button class="button dark" id="retry-session">${wrong.length?'Retry missed questions':'Try this round again'} ${icon('arrow',17)}</button><a class="button" href="${s.lessonId?'#/lesson/'+s.lessonId:'#/practice'}">${s.lessonId?'Back to the lesson':'Another mix'}</a><a class="button ghost" href="#/progress">My progress</a></div>${!storageAvailable?'<p class="tiny muted mt20">Your browser blocked saving. Progress is available in this open session only.</p>':''}</section><section class="review-list" aria-label="Answer review"><div class="section-heading"><h2 style="font-size:24px">Take the “why” with you.</h2></div>${s.answers.map((a,i)=>{const l=byId(a.ref.id),q=l.questions[a.ref.index];return `<article class="review-item"><div class="card-meta">${icon(a.correct?'check':'bolt',15)} ${i+1} · ${e(l.grammar)}</div><h3 class="mt10">${e(q.prompt)}</h3><p>Your answer: ${e(a.answer)}</p>${!a.correct?`<p class="review-correct">Correct answer: ${e(Array.isArray(q.answer)?q.answer[0]:q.answer)}</p>`:''}<p>${e(q.why)}</p><a class="text-link mt10" href="#/lesson/${l.id}" style="font-size:11px">Review the rule ${icon('arrow',13)}</a></article>`;}).join('')}</section></div></div>`,'practice');
  $('#retry-session').addEventListener('click',()=>{if(wrong.length)startSession(wrong.map(a=>a.ref),'Your tricky bits',null,s.returnTo);else startSession(s.refs,s.title,s.lessonId,s.returnTo);});
}
function progress(){const done=LESSONS.filter(l=>completed(l.id)),attempted=LESSONS.filter(l=>state.results[l.id]),saved=LESSONS.filter(l=>state.saved.includes(l.id));shell(`<div class="wrap bottom-space"><section class="page-top"><div class="eyebrow">PROGRESS OVER PERFECTION</div><h1>Look at you go.</h1><p class="section-sub">Every question is practice. Every mistake is a place to grow.</p></section><div class="stats-grid"><div class="stat-card"><div class="stat-value">${Object.keys(state.answers).length*10}</div><div class="stat-label">XP · 10 per unique correct question</div></div><div class="stat-card"><div class="stat-value">${done.length}<span class="muted" style="font-size:20px"> / ${LESSONS.length}</span></div><div class="stat-label">Lesson challenges passed with 4/5 or better</div></div><div class="stat-card"><div class="stat-value">${state.applied.length}</div><div class="stat-label">Real-life tasks tried · self-reported</div></div><div class="stat-card"><div class="stat-value">${state.mistakes.length}</div><div class="stat-label">Tricky questions to revisit</div></div></div><div class="progress-columns"><section class="panel"><h2>Your learning trail.</h2><p class="progress-detail">Your best result from each full lesson challenge.</p>${attempted.length?attempted.map(l=>`<div class="progress-row"><div><strong>${e(l.grammar)}</strong><small>${l.level} · Best ${state.results[l.id].best}/5 ${completed(l.id)?'· Challenge passed':''}</small></div><a href="#/lesson/${l.id}">${completed(l.id)?'Revisit':'Keep going'} →</a></div>`).join(''):`<div class="empty mt20"><h3>Your first win starts here.</h3><p>Try a lesson challenge. Your progress will appear right here.</p><a class="button small dark" href="#/learn">Explore lessons ${icon('arrow',15)}</a></div>`}</section><section class="panel"><h2>Make it stick.</h2><p class="progress-detail">Revisit your tricky bits or jump back into a saved lesson.</p><button class="button small lime mt20" id="review-mistakes" ${state.mistakes.length?'':'disabled'}>${icon('bolt',15)} Practise ${state.mistakes.length} tricky ${state.mistakes.length===1?'bit':'bits'}</button><h3 class="mt20">Saved for later</h3>${saved.length?saved.map(l=>`<div class="progress-row"><div><strong>${e(l.grammar)}</strong><small>${l.level} · ${l.minutes} minutes</small></div><a href="#/lesson/${l.id}">Open →</a></div>`).join(''):'<p class="progress-detail">Tap the bookmark on any lesson to save it here.</p>'}</section></div>${exerciseProgressPanel()}<details class="storage-note"><summary>${storageAvailable?'Your progress is saved on this browser.':'Your browser is blocking progress saving.'}</summary><p>There is no student login or cloud sync in this version. ${storageAvailable?'Clearing browser data or switching devices will not carry this progress over.':'Your progress is only available while this page stays open.'} XP measures practice, not a formal English level.</p><button class="danger-link" id="reset-progress">Reset my progress on this browser</button><div id="reset-confirm" hidden><p>This clears scores, XP, saved lessons and tricky questions.</p><button class="button small" id="cancel-reset">Keep my progress</button> <button class="button small dark" id="confirm-reset">Yes, reset everything</button></div></details></div>`,'progress');
  $('#review-mistakes').addEventListener('click',()=>{practiceMode='review';location.hash='#/practice';});$('#reset-progress').addEventListener('click',()=>{$('#reset-confirm').hidden=false;});$('#cancel-reset').addEventListener('click',()=>{$('#reset-confirm').hidden=true;});$('#confirm-reset').addEventListener('click',()=>{state=fresh();session=null;save();progress();toast('Your progress has been reset. Fresh start.');});
}
function worksheet(id,answers){const l=byId(id);return `<article class="worksheet-preview"><img class="worksheet-logo" src="english-bro-logo.png" alt="English, Bro" width="155" height="52"><div class="worksheet-meta">ENGLISH, BRO. · ${l.level} · ${e(l.grammar)} · ${answers?'TEACHER COPY':'STUDENT WORKSHEET'}</div><h1>${e(l.title)}</h1><p>Name: ____________________________ &nbsp; Date: ______________</p><h2>Learning goals</h2><ul>${LEARNING[id].goals.map(g=>`<li>${e(g)}</li>`).join('')}</ul><h2>01 / Notice the pattern</h2>${LEARNING[id].context?`<p>${e(LEARNING[id].context)}</p>`:''}${LEARNING[id].scene.map(([name,text])=>`<p><strong>${e(name)}:</strong> ${e(text)}</p>`).join('')}<h2>02 / Understand it</h2><p>${e(l.rule)}</p><div class="formula">${e(l.form)}</div>${l.examples.map(([text,note])=>`<p><strong>${e(text)}</strong><br><span class="worksheet-meta">${e(note)}</span></p>`).join('')}<p><strong>Watch this bit:</strong> ${e(l.watchOut)}</p><h2>03 / Try it</h2><p>Choose the correct option or write the missing words.</p><ol>${l.questions.map(q=>`<li>${e(q.prompt)}${q.options?`<br><span class="worksheet-meta">${q.options.map((o,i)=>`${String.fromCharCode(65+i)}) ${e(o)}`).join(' &nbsp; ')}</span>`:'<br>Answer: ______________________________________'}</li>`).join('')}</ol><h2>04 / Use it in your world</h2><p>${e(l.mission)}</p><div class="writing-lines"></div>${answers?`<section class="answer-key"><h2>Answer key & teaching notes</h2><ol>${l.questions.map(q=>`<li><strong>${e(Array.isArray(q.answer)?q.answer.join(' / '):q.answer)}</strong><br>${e(q.why)}</li>`).join('')}</ol><p class="worksheet-meta">The final task is open-ended. Check meaning, the target structure and whether students can explain their choices.</p></section>`:''}<p class="worksheet-meta">English, Bro · Original learning material · British English</p></article>`;}
function printWorksheet(id,answers){$('#print-area').innerHTML=worksheet(id,answers);window.print();}
function teachers(){shell(`<div class="wrap"><section class="page-top"><div class="eyebrow">LESS PREP. MORE CONNECTION.</div><h1>Made for your classroom.</h1><p class="section-sub">Take the same short lessons off-screen. Print a worksheet, add the answer key, and give students something worth talking about.</p></section><section class="teacher-exercise-callout"><div><span class="eyebrow">MORE PRACTICE. READY FOR CLASS.</span><h2>Full exercise pages.</h2><p>Choose a grammar point. Share one link or print a 20-question set with a separate answer key.</p></div><a class="button dark" href="#/exercises">Browse exercise pages ${icon('arrow',17)}</a></section><div class="teacher-intro-grid"><div class="teacher-note"><strong>01 / Get the idea</strong><p>Introduce a clear rule through a familiar context.</p></div><div class="teacher-note"><strong>02 / Give it a go</strong><p>Use the five practice questions individually or in pairs.</p></div><div class="teacher-note"><strong>03 / Make it theirs</strong><p>Finish with a short speaking or writing task.</p></div></div><div class="teacher-layout"><aside class="teacher-tools"><div class="panel"><h2 style="font-size:22px">Your worksheet.</h2><p>Choose a lesson. Preview the handout, then print or save it as a PDF from your browser.</p><div class="field"><label for="teacher-lesson">Lesson</label><select id="teacher-lesson">${LESSONS.map(l=>`<option value="${l.id}" ${l.id===teacherId?'selected':''}>${l.level} · ${e(l.grammar)}</option>`).join('')}</select></div><label class="checkbox-label"><input type="checkbox" id="teacher-answers" ${teacherAnswers?'checked':''}>Include separate answer key</label><button class="button dark full" id="print-teacher">${icon('print',17)} Print / Save as PDF</button><p class="tiny muted mt20">No student names or scores are collected. Student practice progress stays in their own browser.</p></div></aside><section id="worksheet-preview" aria-label="Worksheet preview">${worksheet(teacherId,teacherAnswers)}</section></div></div>`,'teachers');
  $('#teacher-lesson').addEventListener('change',ev=>{teacherId=ev.target.value;$('#worksheet-preview').innerHTML=worksheet(teacherId,teacherAnswers);});$('#teacher-answers').addEventListener('change',ev=>{teacherAnswers=ev.target.checked;$('#worksheet-preview').innerHTML=worksheet(teacherId,teacherAnswers);});$('#print-teacher').addEventListener('click',()=>printWorksheet(teacherId,teacherAnswers));
}
function paths(params=new URLSearchParams()){
  const selected=LEVELS.includes(params.get('level'))?params.get('level'):'All';
  shell(`<div class="wrap bottom-space"><section class="page-top"><div class="eyebrow">KNOW WHERE YOU’RE GOING</div><h1>Your next chapter.</h1><p class="section-sub">Choose a starting level and follow a suggested order. Every lesson takes you from noticing a pattern to using it yourself.</p></section><div class="path-process"><div><span>01</span><strong>Notice it</strong><p>Meet the grammar in a conversation.</p></div><div><span>02</span><strong>Understand it</strong><p>See the pattern and worked examples.</p></div><div><span>03</span><strong>Practise it</strong><p>Get feedback that explains the why.</p></div><div><span>04</span><strong>Use it</strong><p>Make your own message, story or idea.</p></div></div><nav class="pills path-pills" aria-label="Select learning path">${['All',...LEVELS].map(level=>`<a class="pill ${selected===level?'active':''}" href="#/paths${level==='All'?'':'?level='+level}" ${selected===level?'aria-current="page"':''}>${level==='All'?'All paths':level}</a>`).join('')}</nav><div class="paths-grid">${PATHS.filter(p=>selected==='All'||p.level===selected).map(p=>{
    const passed=p.order.filter(completed).length,next=p.order.find(id=>!completed(id))||p.order[0];
    return `<section class="path-card"><div class="path-card-top" style="background:${p.color}"><div class="eyebrow">${p.level} · ${p.order.length} LESSONS</div><h2>${e(p.title)}</h2><p>${e(p.outcome)}</p></div><div class="path-card-body"><div class="results-count"><span>${passed}/${p.order.length} challenges passed</span><span>${p.order.filter(id=>state.applied.includes(id)).length} tasks tried</span></div><div class="progress-bar"><span style="width:${passed/p.order.length*100}%"></span></div><ol class="path-lessons">${p.order.map((id,i)=>{const l=byId(id);return `<li><span class="path-step ${completed(id)?'done':''}">${completed(id)?icon('check',13):String(i+1).padStart(2,'0')}</span><div><a href="#/lesson/${id}">${e(l.grammar)}</a><small>${l.minutes} minutes${state.applied.includes(id)?' · Real-life task tried':''}</small></div><a class="arrow-circle" href="#/lesson/${id}" aria-label="Open ${e(l.grammar)}">${icon('arrow',14)}</a></li>`;}).join('')}</ol><a class="button dark full" href="#/lesson/${next}">${passed===p.order.length?'Revisit this path':passed?'Continue this path':'Start this path'} ${icon('arrow',16)}</a></div></section>`;
  }).join('')}</div><p class="practice-disclaimer">These paths organise the current grammar collection. A complete language level also involves vocabulary, listening, reading, speaking and writing.</p></div>`,'paths');
}
function about(){shell(`<div class="wrap"><section class="page-top"><div class="eyebrow">A LITTLE ABOUT US</div><h1>Good English. Your world.</h1><p class="section-sub">English, Bro is a project about making useful English feel closer to everyday life.</p></section><div class="practice-container"><section class="panel"><h2>Everyone’s invited.</h2><p class="rule-text">“Bro” is the working title and a friendly tone. These lessons are for everyone. Expect clear explanations, original examples and opportunities to speak and write, alongside the occasional group-chat reference.</p></section><section class="panel"><h2>What’s here so far?</h2><p class="rule-text">${LESSONS.length} introductory lesson units, ${EXERCISE_SETS.length} full exercise pages with ${EXERCISE_SETS.reduce((n,s)=>n+exerciseItems(s).length,0)} exercises, ${LESSONS.reduce((n,l)=>n+l.questions.length,0)} quick-challenge questions and printable classroom worksheets. The lessons range from A1 to B2 in intended difficulty and use British English. This is an initial collection, not a complete CEFR syllabus, accredited course or formal level assessment. We’re starting with English; other languages can come later.</p></section><section class="panel"><h2>Your practice, your browser.</h2><p class="rule-text">The app stores quiz progress, saved lessons and questions to review in local storage on this browser. It does not send those practice records to a server, create student accounts, or include advertising or analytics scripts. You can reset your progress from My progress. Google Fonts may receive a normal font request; if it cannot load, the site uses system fonts. Hosting and any access sign-in are provided by the hosting platform under its own policies.</p><a class="text-link mt20" href="#/progress">Manage my progress ${icon('arrow',16)}</a></section><section class="panel"><h2>Original material.</h2><p class="rule-text">The explanations, examples, practice questions and visual identity here were created for English, Bro. Familiar grammar-reference patterns helped inform the learning structure.</p></section></div></div>`,'');}
function notFound(){shell(`<div class="wrap not-found"><h1>This page went off-script.</h1><p>Let’s get you back to something useful.</p><a class="button dark" href="#/learn">Find a lesson ${icon('arrow',17)}</a></div>`,'');}
function route(){const raw=location.hash.replace(/^#\/?/,'');const [path,query='']=raw.split('?'),parts=path.split('/').filter(Boolean),params=new URLSearchParams(query),page=parts[0]||'home';
  if(page==='home')home();else if(page==='learn')learn(params);else if(page==='exercises'){if(parts[1])exercise(parts[1]);else exerciseHub(params);}else if(page==='lesson')lesson(parts[1]);else if(page==='quiz'){const l=byId(parts[1]);if(l){startSession(refsFor([l]),l.grammar,l.id,'#/lesson/'+l.id);return;}notFound();}else if(page==='paths')paths(params);else if(page==='practice')practice();else if(page==='session')renderSession();else if(page==='progress')progress();else if(page==='teachers')teachers();else if(page==='about')about();else notFound();
  const titles={home:'English for your actual life',learn:'Find a lesson',paths:'Learning paths',lesson:byId(parts[1])?.grammar||'Lesson',practice:'A little brain workout',session:'Practice',progress:'My progress',teachers:'For teachers',exercises:parts[1]?(byId(parts[1])?.grammar||'Exercises')+' exercises':'Exercise pages',about:'About & privacy'};document.title=`${titles[page]||'Page not found'} — English, Bro`;
  window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});
}
